import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnInit,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { BoatownerService } from '../boatowner.service';
import { OwnerBookingsService, BackendBooking } from '../owner-bookings.service';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

interface ClientRow {
  uid: string;
  fullName?: string;
  email?: string;
  phone?: string;

  bookingsCount: number;
  lastBookingAt?: number; // millis
  lastBookingId?: string;
}

@Component({
  selector: 'app-owner-clients',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './owner-clients.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class OwnerClientsComponent implements OnInit {
  loading = false;
  error?: string;

  mainpageId?: string;

  q = '';
  clients: ClientRow[] = [];

  constructor(
    private ctx: BoatownerService,
    private bookingsSvc: OwnerBookingsService,
    private storeDb: StoreDbService,
    private cdr: ChangeDetectorRef
  ) {}

  async ngOnInit(): Promise<void> {
    await this.reload();
  }

  async reload(): Promise<void> {
    this.loading = true;
    this.error = undefined;
    this.cdr.markForCheck();

    try {
      this.mainpageId = await this.ctx.requireOwnerMainpageId();
      const bookings = await this.bookingsSvc.listBookingsForOwner(this.mainpageId);

      this.clients = await this.buildClients(bookings);
    } catch (e: any) {
      this.error = e?.message || 'Failed to load clients.';
      this.clients = [];
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  private async buildClients(bookings: BackendBooking[]): Promise<ClientRow[]> {
    const byUid = new Map<string, ClientRow>();

    for (const b of bookings) {
      const uid = b.customer?.uid;
      if (!uid) continue;

      const lastAt =
        b.audit?.createdAt ??
        b.audit?.requestedAt ??
        b.modifiedTS ??
        (b.time?.startAt ? new Date(b.time.startAt).getTime() : 0);

      const existing = byUid.get(uid);
      if (!existing) {
        byUid.set(uid, {
          uid,
          fullName: b.customer?.fullName,
          email: b.customer?.email,
          phone: b.customer?.phone,
          bookingsCount: 1,
          lastBookingAt: lastAt,
          lastBookingId: b.bookingId,
        });
      } else {
        existing.bookingsCount += 1;
        if ((existing.lastBookingAt || 0) < lastAt) {
          existing.lastBookingAt = lastAt;
          existing.lastBookingId = b.bookingId;
        }
        // keep best-known info
        existing.fullName = existing.fullName || b.customer?.fullName;
        existing.email = existing.email || b.customer?.email;
        existing.phone = existing.phone || b.customer?.phone;
      }
    }

    // Pull backendusers to enrich info (best effort)
    const rows = Array.from(byUid.values());
    const enriched = await Promise.all(
      rows.map(async r => {
        try {
          const u = await this.storeDb.getObject<any>(OBJECTNAME.bnUsers, r.uid);
          if (u) {
            return {
              ...r,
              fullName: r.fullName || u.fullName || u.displayName || u.name,
              email: r.email || u.email,
              phone: r.phone || u.phone,
            } as ClientRow;
          }
          return r;
        } catch {
          return r;
        }
      })
    );

    // sort by recency
    enriched.sort((a, b) => (b.lastBookingAt || 0) - (a.lastBookingAt || 0));
    return enriched;
  }

  get filtered(): ClientRow[] {
    const q = (this.q || '').trim().toLowerCase();
    if (!q) return this.clients;

    return this.clients.filter(c => {
      const t = `${c.fullName || ''} ${c.email || ''} ${c.phone || ''} ${c.uid}`.toLowerCase();
      return t.includes(q);
    });
  }

  formatDate(ms?: number): string {
    if (!ms) return '—';
    try {
      return new Date(ms).toLocaleString();
    } catch {
      return String(ms);
    }
  }
}
