// owner-config-xls.component.ts
import {
  Component,
  OnInit,
  OnDestroy,
  ChangeDetectionStrategy,
  ChangeDetectorRef
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Subscription } from 'rxjs';

import { UtilsService, StoreDbService, OBJECTNAME, Users } from 'godigital-lib';

// This is the same LayoutService you use in the header:
// header.component.ts uses: constructor(public boatsSvc: LayoutService, ...)
import { BoatownerService } from '../boatowner.service'; // <-- adjust path

interface OwnerXlsConfig {
  storagePath?: string;       // e.g. "owner-config/<ownerId>/boatify-config.xlsx"
  downloadUrl?: string;       // public URL from Storage
  updatedAt?: number;         // timestamp (ms)
  lastImportAt?: number;      // timestamp (ms)
  lastImportStatus?: string;  // e.g. "ok", "error: …"
  lastImportMessage?: string; // optional human-readable message
}

@Component({
  selector: 'app-owner-config-xls',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './owner-config-xls.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OwnerConfigXlsComponent implements OnInit, OnDestroy {

  ownerId?: string;

  loading = true;
  error?: string;
  success?: string;

  xlsConfig?: OwnerXlsConfig;

  selectedFile?: File;
  uploading = false;
  importing = false;

  private subscriptions = new Subscription();

  constructor(
    private http: HttpClient,
    private storeDb: StoreDbService,
    public utilsSvc: UtilsService,
    public boatownerSvc: BoatownerService,         // ⬅️ to access mainSvc.getUser()
    private cdr: ChangeDetectorRef
  ) { }

  ngOnInit() {
    this.loading = true;
    this.error = undefined;
    this.success = undefined;
    this.cdr.markForCheck();

    // 🔑 Subscribe to the logged user (getUser returns an Observable)
    this.subscriptions.add(
      this.boatownerSvc.mainSvc.getUser().subscribe(user => {
        // Avoid async directly in subscribe; delegate:
        this.handleUserChange(user as Users | null);
      })
    );
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  /** Called whenever the logged user changes */
  private async handleUserChange(user: Users | null): Promise<void> {
    this.loading = true;
    this.error = undefined;
    this.success = undefined;
    this.cdr.markForCheck();

    try {
      if (!user || !user.userId) {
        this.ownerId = undefined;
        this.xlsConfig = undefined;
        this.error = 'You must be logged in as a boat owner to access this page.';
        return;
      }

      this.ownerId = user.userId;

      // Optionally: check role here, e.g. user.role === 'OWNER', etc.
      // if (user.role !== USERROLE.OWNER) { ... }

      // Load XLS config metadata from RTDB
      await this.loadXlsConfig();
    } catch (e: any) {
      console.error('Error in handleUserChange', e);
      this.error = 'Failed to load your configuration info.';
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  /** Load /backendowners/<ownerId>/xlsConfig from Realtime DB */
  private async loadXlsConfig(): Promise<void> {
    if (!this.ownerId) return;

    const collectionName = (OBJECTNAME as any).backendowners || 'backendowners';

    const node = await this.storeDb.getObject(
      collectionName,
      this.ownerId
    ) as any | null;

    this.xlsConfig = node?.xlsConfig || undefined;
  }

  // -------------- FILE HANDLING --------------

  onFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (!input.files || input.files.length === 0) {
      this.selectedFile = undefined;
      return;
    }
    this.selectedFile = input.files[0];
    this.error = undefined;
    this.success = undefined;
    this.cdr.markForCheck();
  }

  async uploadXls(): Promise<void> {
    if (!this.ownerId) {
      this.error = 'No owner id found. Please log in again.';
      this.cdr.markForCheck();
      return;
    }
    if (!this.selectedFile) {
      this.error = 'Please choose a spreadsheet file first.';
      this.cdr.markForCheck();
      return;
    }

    this.uploading = true;
    this.error = undefined;
    this.success = undefined;
    this.cdr.markForCheck();

    try {
      const formData = new FormData();
      formData.append('ownerId', this.ownerId);
      formData.append('file', this.selectedFile);

      const url = `${this.utilsSvc.backendURL}/boatowners/config/xls/upload`;

      const res = await this.http.post<OwnerXlsConfig>(url, formData).toPromise();

      this.success = 'Spreadsheet uploaded successfully.';
      if (res) {
        this.xlsConfig = res;
      } else {
        await this.loadXlsConfig();
      }
    } catch (e: any) {
      console.error('uploadXls error', e);
      this.error = e?.error?.message || 'Failed to upload spreadsheet.';
    } finally {
      this.uploading = false;
      this.cdr.markForCheck();
    }
  }

  downloadXls(): void {
    if (!this.xlsConfig?.downloadUrl) {
      this.error = 'No spreadsheet found to download.';
      this.cdr.markForCheck();
      return;
    }
    window.open(this.xlsConfig.downloadUrl, '_blank');
  }

  async triggerImport(): Promise<void> {
    if (!this.ownerId) {
      this.error = 'No owner id found. Please log in again.';
      this.cdr.markForCheck();
      return;
    }

    this.importing = true;
    this.error = undefined;
    this.success = undefined;
    this.cdr.markForCheck();

    try {
      const url = `${this.utilsSvc.backendURL}/boatowners/config/xls/import`;
      const body = { ownerId: this.ownerId };
      const res = await this.http.post<OwnerXlsConfig | any>(url, body).toPromise();

      this.success = 'Import started / completed. Refresh later if needed.';
      if (res?.xlsConfig) {
        this.xlsConfig = res.xlsConfig;
      } else {
        await this.loadXlsConfig();
      }
    } catch (e: any) {
      console.error('triggerImport error', e);
      this.error = e?.error?.message || 'Failed to trigger import.';
    } finally {
      this.importing = false;
      this.cdr.markForCheck();
    }
  }

  // -------------- SMALL HELPERS --------------

  get lastUpdatedLabel(): string {
    if (!this.xlsConfig?.updatedAt) return 'Never uploaded yet';
    const d = new Date(this.xlsConfig.updatedAt);
    return `Last updated: ${d.toLocaleDateString()} ${d.toLocaleTimeString()}`;
  }

  get lastImportLabel(): string {
    if (!this.xlsConfig?.lastImportAt) return 'Never imported yet';
    const d = new Date(this.xlsConfig.lastImportAt);
    const status = this.xlsConfig.lastImportStatus || 'unknown';
    return `Last import: ${d.toLocaleDateString()} ${d.toLocaleTimeString()} (${status})`;
  }
}
