import { Injectable } from '@angular/core';
import { UsersService, Users, } from 'godigital-lib';
import { Router, } from '@angular/router';
import { HttpClient, HttpParams, HttpHeaders } from '@angular/common/http';
import { UtilsService, EDITSLIDE } from 'godigital-lib';
import { LocalUtilsService } from '../services/services.service';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { NgxSpinnerService } from 'ngx-spinner';
import { ServicesService, StoreDbService, OBJECTNAME } from 'godigital-lib';

import { firstValueFrom } from 'rxjs';
import { filter, take, timeout, catchError } from 'rxjs/operators';

type OwnerMainpageId = string; // e.g. owner-home-layali


@Injectable({
  providedIn: 'root'
})
export class BoatownerService {
  public signinForm: FormGroup;
  public address;
  public currentPlaceId;
  constructor(
    private router: Router,
    public mainSvc: ServicesService,
    private utilsSvc: UtilsService,
    private usersSvc: UsersService,
    public localUtilsSvc: LocalUtilsService,
    public fb: FormBuilder,
    public http: HttpClient,
    private storeDb: StoreDbService,
    public spinner: NgxSpinnerService,
  ) { }

  getGoogleMetadata(gmid: string) {
    return new Promise((resolve, reject) => {
      const params = new HttpParams()
        .set('placeId', gmid);
      // tslint:disable-next-line: deprecation
      this.http.get(this.utilsSvc.backendURL + 'utils/getGoogleMetadata', { params }).subscribe(
        data => {
          resolve(data);
        },
        error => {
          console.log('error=', error);
          reject(error);
        }
      );

    });
  }

  updateBackendUser(adnUser) {
    return new Promise((resolve, reject) => {
      this.usersSvc.updateUser(adnUser).then(
        data => resolve(data), error => reject(error)
      );
    });
  }

  forgotPwd(emailPwdRecovery) {
    this.usersSvc.resetPwdUser(emailPwdRecovery).then(
      () => {
        this.localUtilsSvc.showModalNoButton('password reset',
          'An email for recovering your password has been sent to this email adress.');
        this.router.navigate(['/login']);
      },
      error => {
        this.localUtilsSvc.showModalNoButton('password reset',
          'no account exists under this email. please check again.');
        this.router.navigate(['/login']);
      }
    );
  }

  get wnGuest() {
    return this.localUtilsSvc.wnGuest;
  }
  set wnGuest(value: Users) {
    this.localUtilsSvc.wnGuest = value;
  }

  get errorMessage() {
    return this.localUtilsSvc.errorMessage;
  }
  set errorMessage(value) {
    this.localUtilsSvc.errorMessage = value;
  }

  get version() {
    return this.mainSvc.version;
  }
  set version(value) {
    this.mainSvc.version = value;
  }

  /**
   * Wait until Firebase auth session is restored and we have a user.
   * (Fixes "not logged in" when user is actually logged in.)
   */
  async requireAuthUser(timeoutMs = 8000): Promise<any> {
    if (this.storeDb.currentUser) return this.storeDb.currentUser;

    const user = await firstValueFrom(
      this.storeDb.authState$.pipe(
        filter((u): u is any => !!u),
        take(1),
        timeout(timeoutMs),
        catchError(() => {
          throw new Error('Not logged in (auth session not ready). Please refresh or re-login.');
        })
      )
    );

    return user;
  }

  /**
   * ✅ RTDB: backendowners/primaryUserId/<uid>
   * The node can be either:
   *  - full owner record
   *  - mapping object containing ownerId / mainpageId
   *  - or even a string "owner-home-xxx"
   */
  async requireOwnerMainpageId(): Promise<OwnerMainpageId> {
    const user = await this.requireAuthUser();

    const base = (OBJECTNAME as any).bnOwners || 'backendowners';
    const path = `${base}/primaryUserId/${user.uid}`;

    const node: any = await this.storeDb.getObject<any>(path);

    if (!node) {
      throw new Error(
        `Logged in as ${user.uid} but no owner mapping found at ${path}.`
      );
    }

    // Allow several shapes:
    // 1) node is string: "owner-home-layali"
    if (typeof node === 'string') {
      return this.normalizeMainpageId(node);
    }

    // 2) node is object containing ownerId/mainpageId
    const raw =
      node.ownerId ||
      node.mainpageId ||
      node.id ||
      node.key;

    if (raw && typeof raw === 'string') {
      return this.normalizeMainpageId(raw);
    }

    // 3) node is a full owner record stored directly under that uid (rare)
    // and its key is not available here -> require ownerId/mainpageId field inside.
    throw new Error(
      `Owner mapping found at ${path} but it doesn't contain ownerId/mainpageId (or it's not a string).`
    );
  }

  async getOwnerMapping(): Promise<any> {
    const user = await this.requireAuthUser();
    const base = (OBJECTNAME as any).bnOwners || 'backendowners';
    const path = `${base}/primaryUserId/${user.uid}`;
    return await this.storeDb.getObject<any>(path);
  }

  private normalizeMainpageId(raw: string): OwnerMainpageId {
    const lower = (raw || '').trim().toLowerCase();
    if (!lower) throw new Error('Invalid ownerId/mainpageId (empty).');
    return lower.startsWith('owner-home-') ? lower : `owner-home-${lower}`;
  }
}
