import { Injectable } from '@angular/core';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

export type BookingStatus =
  | 'requested'
  | 'confirmed'
  | 'cancelled'
  | 'declined'
  | 'expired'
  | 'completed';

export type BookingType = 'boat' | 'event';

export interface BackendBookingDoc {
  bookingId: string;
  status: BookingStatus;
  type: BookingType;

  mainpageId: string; // owner-home-xxx
  ownerId: string;    // same as mainpageId for owner dashboards
  boatId: string;
  eventId?: string;

  customer: {
    uid: string;
    fullName?: string;
    email?: string;
    phone?: string;
  };

  party?: {
    adults?: number;
    children?: number;
    total?: number;
  };

  time: {
    startAt: string; // ISO
    endAt: string;   // ISO
  };

  locations?: {
    pickup?: { label?: string; placeId?: string; lat?: number; lng?: number };
    dropoff?: { label?: string; placeId?: string; lat?: number; lng?: number };
  };

  extras?: {
    selected?: Record<string, boolean>;
    items?: Array<{ code: string; label: string; qty?: number; unitPrice?: number }>;
  };

  pricing?: {
    currency?: string;
    baseAmount?: number;
    extrasAmount?: number;
    serviceFee?: number;
    totalAmount?: number;
    depositAmount?: number;
    taxAmount?: number;
  };

  notes?: { customerNote?: string; ownerNote?: string };

  audit?: {
    createdAt?: number;
    updatedAt?: number;
    requestedAt?: number;
    confirmedAt?: number;
    cancelledAt?: number;
    cancelledBy?: 'customer' | 'owner' | 'system';
  };

  // your StoreDbService auto-adds modifiedTS on updateObject/partialUpdateObject
  modifiedTS?: number;
}

export interface BackendBooking {
  bookingId: string;
  ownerId: string;      // "owner-home-layali"
  mainpageId?: string;  // same as ownerId in your data
  boatId?: string;      // "1000002"
  status?: string;
  time?: { startAt?: string; endAt?: string };
  customer?: { uid?: string; fullName?: string; email?: string; phone?: string };
  pricing?: { totalAmount?: number; currency?: string };
  [k: string]: any;
}

@Injectable({ providedIn: 'root' })
export class OwnerBookingsService {
  constructor(private storeDb: StoreDbService) {}

  // ---------------------------------------------------------------------------
  // INDEX PATHS
  // ---------------------------------------------------------------------------

  private byOwnerIndexPath(ownerMainpageId: string): string {
    return `backendbookingIndex/byOwner/${ownerMainpageId}`;
  }

  private byOwnerIndexItemPath(ownerMainpageId: string, bookingId: string): string {
    return `backendbookingIndex/byOwner/${ownerMainpageId}/${bookingId}`;
  }

  // ---------------------------------------------------------------------------
  // LIST (Option 1)
  // ---------------------------------------------------------------------------

  /** Returns bookingIds for this owner (fast) */
  async listBookingIdsForOwner(ownerMainpageId: string): Promise<string[]> {
    const node = await this.storeDb.getObject<any>(this.byOwnerIndexPath(ownerMainpageId));
    if (!node || typeof node !== 'object') return [];
    return Object.keys(node).filter(k => !!k);
  }

  /** Fetch bookings by ids (flat docs). Missing docs are skipped. */
  async getBookingsByIds(ids: string[]): Promise<BackendBookingDoc[]> {
    if (!ids?.length) return [];
    const docs = await Promise.all(
      ids.map(id => this.storeDb.getObject<BackendBookingDoc>(OBJECTNAME.bnBookings, id))
    );
    return docs.filter((x): x is BackendBookingDoc => !!x && !!x.bookingId);
  }

  // ---------------------------------------------------------------------------
  // CREATE (writes booking + index)
  // ---------------------------------------------------------------------------

  async createBooking(doc: Omit<BackendBookingDoc, 'bookingId'>): Promise<BackendBookingDoc> {
    this.storeDb['ensureReady']?.(); // in case your lib exposes it; safe if not

    const bookingId = this.storeDb.db.ref(OBJECTNAME.bnBookings).push().key;
    if (!bookingId) throw new Error('Unable to generate bookingId.');

    const now = Date.now();

    const full: BackendBookingDoc = {
      ...doc,
      bookingId,
      audit: {
        ...(doc.audit || {}),
        createdAt: doc.audit?.createdAt ?? now,
        updatedAt: now,
        requestedAt: doc.audit?.requestedAt ?? now,
      },
    };

    // 1) write booking doc (flat)
    await this.storeDb.updateObject(OBJECTNAME.bnBookings, full, bookingId);

    // 2) index for owner (boolean node -> use raw .set(true))
    await this.storeDb.db.ref(this.byOwnerIndexItemPath(full.ownerId, bookingId)).set(true);

    return full;
  }

  // ---------------------------------------------------------------------------
  // STATUS ACTIONS (owner)
  // ---------------------------------------------------------------------------

  async setStatus(
    bookingId: string,
    next: BookingStatus,
    cancelledBy?: 'customer' | 'owner' | 'system'
  ): Promise<void> {
    const now = Date.now();

    const patch: any = {
      status: next,
      audit: {
        updatedAt: now,
      },
    };

    if (next === 'confirmed') patch.audit.confirmedAt = now;
    if (next === 'cancelled') {
      patch.audit.cancelledAt = now;
      patch.audit.cancelledBy = cancelledBy || 'owner';
    }

    // partial update booking doc
    await this.storeDb.partialUpdateObject(OBJECTNAME.bnBookings, patch, bookingId);
  }

  // ---------------------------------------------------------------------------
  // OPTIONAL: Repair / Ensure index exists for booking docs (admin tool)
  // ---------------------------------------------------------------------------

  async ensureOwnerIndexForBooking(booking: BackendBookingDoc): Promise<void> {
    if (!booking?.ownerId || !booking?.bookingId) return;
    await this.storeDb.db.ref(this.byOwnerIndexItemPath(booking.ownerId, booking.bookingId)).set(true);
  }

  async removeOwnerIndexForBooking(ownerMainpageId: string, bookingId: string): Promise<void> {
    await this.storeDb.db.ref(this.byOwnerIndexItemPath(ownerMainpageId, bookingId)).remove();
  }


  async listBookingsForOwner(ownerId: string): Promise<BackendBooking[]> {
    const root: any = await this.storeDb.getObject<any>('backendbookings', -1);

    if (!root || typeof root !== 'object') return [];

    // ---------------------------------------------------------------------
    // A) Indexed schema: { byOwner, byId } OR { byOwner, byId, ... }
    // ---------------------------------------------------------------------
    if (root.byOwner && root.byOwner[ownerId]) {
      const idsMap = root.byOwner[ownerId] || {};
      const bookingIds = Object.keys(idsMap).filter(k => !!k);

      // if "byId" exists, hydrate from it
      const byId = root.byId || {};
      const bookings = bookingIds
        .map(id => byId[id] ? ({ ...byId[id], bookingId: byId[id].bookingId || id } as BackendBooking) : null)
        .filter(Boolean) as BackendBooking[];

      // Fallback: if not in byId, you could fetch each booking path individually (optional)
      return this.sortBookings(bookings);
    }

    // ---------------------------------------------------------------------
    // B) Flat schema: { "<bookingId>": { ownerId, ... }, ... }
    // Need to ignore index-like keys if any remain.
    // ---------------------------------------------------------------------
    const RESERVED_KEYS = new Set(['byOwner', 'byBoat', 'byCustomer', 'byId']);
    const bookings: BackendBooking[] = [];

    for (const [key, val] of Object.entries(root)) {
      if (RESERVED_KEYS.has(key)) continue;
      if (!val || typeof val !== 'object') continue;

      const b = val as any;
      const bOwnerId = b.ownerId || b.mainpageId;
      if (bOwnerId !== ownerId) continue;

      bookings.push({
        ...b,
        bookingId: b.bookingId || key,
      } as BackendBooking);
    }

    return this.sortBookings(bookings);
  }

  private sortBookings(bookings: BackendBooking[]): BackendBooking[] {
    return bookings.sort((a, b) => {
      const ta = Date.parse(a?.time?.startAt || '') || 0;
      const tb = Date.parse(b?.time?.startAt || '') || 0;
      return tb - ta; // most recent first
    });
  }
}
