import {
  Component,
  OnInit,
  OnDestroy,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
} from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Subscription } from 'rxjs';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

interface HeroBadge {
  label: string;
  icon?: string;
  style?: string;
}

interface ExperienceItem {
  icon?: string;
  title: string;
  note: string;
}

interface SignatureTrip {
  image: string;
  title: string;
  subtitle: string;
  link: string;
  ctaLabel: string;
  ctaLink: string;
  footerLeft: string;
}

interface Testimonial {
  title: string;
  text: string;
  author: string;
  origin: string;
}

interface MainpageDoc {
  mainpageId: string;
  ownerId: string;
  siteName: string;

  noticeText: string;
  noticeCtaLabel: string;
  noticeCtaLink: string;

  heroTitle: string;
  heroLead: string;
  heroImage: string;

  heroPrimaryCtaLabel: string;
  heroPrimaryCtaLink: string;
  heroSecondaryCtaLabel: string;
  heroSecondaryCtaLink: string;
  heroBadges_json: HeroBadge[];

  experienceTitle: string;
  experienceItems_json: ExperienceItem[];

  signatureTitle: string;
  signatureTrips_json: SignatureTrip[];

  aboutBoatTitle: string;
  aboutBoatText: string;
  aboutBoatBadges_json: string[];
  aboutBoatImage: string;
  aboutBoatLink?: string;

  testimonialsTitle: string;
  testimonials_json: Testimonial[];

  galleryCtaLabel: string;
  galleryCtaLink: string;
}

/** Canonical boat object stored under backendboats/<mainpageId>/<boatId> */
interface BoatDoc {
  boatId: string;
  ownerId?: string;

  name?: string;
  model?: string;
  type?: string;

  shortDescription?: string;
  detailedDescription?: string;

  gallery?: string[];
  image?: string;
  heroImage?: string;

  ctaLabel?: string;
  ctaLink?: string;

  capacity?: number;
  cabins?: number;
  bathrooms?: number;
  overnightGuests?: number;

  specs?: any;
  equipment?: string[];
  comfort?: string[];
}

interface SkipperSummary {
  ownerId: string;
  skipperId?: string;
  name: string;
  role?: string;
  shortBio?: string;
  experienceYears?: number;
  languages?: string[];
  photoUrls: string[];
}

interface EventCard {
  eventId: string;
  title: string;
  subtitle?: string;
  imageUrls: string[];
  durationLabel?: string;
  locationLabel?: string;
  footerLeft?: string;
  ctaLabel?: string;
}

@Component({
  selector: 'app-mainpage',
  templateUrl: './mainpage.component.html',
  styleUrls: ['./mainpage.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MainpageComponent implements OnInit, OnDestroy {
  mainpageId!: string;

  mainpage?: MainpageDoc;
  boat?: BoatDoc;
  skipper?: SkipperSummary;
  events: EventCard[] = [];

  loading = false;
  error?: string;

  heroImageUrl?: string;
  boatImageUrls: string[] = [];

  /** Storage root folder in bucket */
  private readonly storageRootFolder = 'mainpages';

  private subs = new Subscription();

  constructor(
    private route: ActivatedRoute,
    private storeDb: StoreDbService,
    private cdr: ChangeDetectorRef
  ) {}

  // ---------------------------------------------------------------------------
  // LIFECYCLE
  // ---------------------------------------------------------------------------

  ngOnInit(): void {
    this.subs.add(
      this.route.queryParamMap.subscribe((params) => {
        const rawFromQuery = params.get('mainpage');
        const raw = rawFromQuery || this.detectMainpageFromSubdomain() || 'layali';
        const { id } = this.normalizeMainpageId(raw);

        if (this.mainpageId === id && this.mainpage) return;
        void this.loadAllForMainpage(id);
      })
    );
  }

  ngOnDestroy(): void {
    this.subs.unsubscribe();
  }

  // ---------------------------------------------------------------------------
  // MAIN LOADER
  // ---------------------------------------------------------------------------

  private async loadAllForMainpage(id: string): Promise<void> {
    this.mainpageId = id;

//    this.mainpage = undefined;
    this.boat = undefined;
    this.skipper = undefined;
    this.events = [];
    this.boatImageUrls = [];
    this.heroImageUrl = undefined;

    this.error = undefined;
    this.loading = true;
    this.cdr.markForCheck();

    try {
      // 1) mainpage doc (marketing/homepage config)
      await this.loadMainpage();

      // 2) hero image (bucket aligned: mainpages/<id>/home/<file>)
      this.heroImageUrl = await this.resolvePathToDownloadUrl(this.mainpage?.heroImage);

      // 3) boat doc from RTDB (backendboats/<mainpageId>/<boatId>)
      await this.loadBoatCanonical(this.mainpageId);

      // 4) boat images: list from Storage mainpages/<id>/boat (flat + recursive) and merge RTDB gallery if any
      await this.loadBoatImagesAligned();

      // 5) skipper summary from RTDB (backendskippers/<mainpageId>/skippers/<skipperId>) + storage fallback
      await this.loadSkipperFromRtdb(this.mainpageId);

      // 6) events
      await this.loadEvents(this.mainpageId);
    } catch (err: any) {
      console.error('[mainpage] load error', err);
      this.error = err?.message || 'Failed to load homepage content.';
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  // ---------------------------------------------------------------------------
  // MAINPAGE ID RESOLUTION
  // ---------------------------------------------------------------------------

  private normalizeMainpageId(raw: string): { id: string; slug: string } {
    const trimmed = (raw || '').trim();
    const lower = trimmed.toLowerCase();

    if (lower.startsWith('owner-home-')) {
      const slug = lower.substring('owner-home-'.length);
      return { id: lower, slug };
    }
    return { id: `owner-home-${lower}`, slug: lower };
  }

  private detectMainpageFromSubdomain(): string | null {
    if (typeof window === 'undefined') return null;
    const host = window.location.hostname;
    const parts = host.split('.');
    if (parts.length > 2) {
      const sub = parts[0];
      if (sub && sub !== 'www' && sub !== 'localhost') return sub;
    }
    return null;
  }

  // ---------------------------------------------------------------------------
  // DATA LOADERS
  // ---------------------------------------------------------------------------

  private async loadMainpage(): Promise<void> {
    // New RTDB structure: backendowners/mainpage (single document)
    const doc = await this.storeDb.getObject<MainpageDoc>('backendowners/mainpage', null as any);

    if (!doc) {
      this.error = 'Homepage configuration not found.';
      throw new Error('mainpage not found');
    }

    if (!doc.mainpageId) (doc as any).mainpageId = this.mainpageId;
    this.mainpage = doc;
  }

  /**
   * ✅ Canonical RTDB:
   * backendboats/<mainpageId>/<boatId>
   *
   * IMPORTANT:
   * - Ignores the legacy alias node "boat" if it exists.
   * - If multiple boats exist, picks:
   *    1) src.isDefault === true
   *    2) else first numeric-like id
   *    3) else first remaining key (stable-ish alphabetical)
   */
  private async loadBoatCanonical(mainpageId: string): Promise<void> {
    // New RTDB structure: backendowners/boats/{boatId}/boat
    const node = await this.storeDb.getObject<any>('backendowners/boats', null as any);

    if (!node || typeof node !== 'object') {
      this.boat = undefined;
      return;
    }

    // Exclude legacy alias
    const boatKeys = Object.keys(node).filter(
      (k) => k && k !== 'boat' && typeof node[k] === 'object' && node[k] !== null
    );

    if (!boatKeys.length) {
      this.boat = undefined;
      return;
    }

    // 1) Prefer isDefault=true
    const defaultKey = boatKeys.find((k) => node[k]?.isDefault === true);

    // 2) Prefer "unique number" ids (all digits)
    const numericKeys = boatKeys.filter((k) => /^\d+$/.test(k)).sort((a, b) => Number(a) - Number(b));

    // 3) Fallback alphabetical
    const alphaKeys = [...boatKeys].sort((a, b) => a.localeCompare(b));

    const chosenKey = defaultKey || numericKeys[0] || alphaKeys[0];
    // Each boat is stored as { boat: {...}, bookings:..., ... }
    const src = node[chosenKey]?.boat || node[chosenKey] || {};

    this.boat = {
      boatId: String(src.boatId || chosenKey),
      ownerId: src.ownerId || this.mainpage?.ownerId || mainpageId,

      name: src.name,
      model: src.model,
      type: src.type,

      shortDescription: src.shortDescription,
      detailedDescription: src.detailedDescription,

      gallery: Array.isArray(src.gallery) ? src.gallery : [],
      image: src.image || src.coverImage || src.mainImage,
      heroImage: src.heroImage,

      ctaLabel: src.ctaLabel,
      ctaLink: src.ctaLink,

      capacity: src.capacity,
      cabins: src.cabins,
      bathrooms: src.bathrooms,
      overnightGuests: src.overnightGuests,

      specs: src.specs,
      equipment: Array.isArray(src.equipment) ? src.equipment : [],
      comfort: Array.isArray(src.comfort) ? src.comfort : [],
    };
  }

  /**
   * ✅ Bucket alignment:
   * mainpages/<id>/boat/*  AND sometimes mainpages/<id>/boat/<subfolder>/*
   *
   * Strategy:
   * 1) list images from Storage (flat + recursive)
   * 2) optionally merge resolved RTDB gallery
   */
  private async loadBoatImagesAligned(): Promise<void> {
    if (!this.mainpageId) {
      this.boatImageUrls = [];
      return;
    }

    // 1) STORAGE source of truth
    const boatRoot = `${this.storageRootFolder}/${this.mainpageId}/boat`;
    const flat = await this.storeDb.listImageUrlsFlat(boatRoot);
    const recursive = await this.storeDb.listImageUrlsRecursive(boatRoot);

    const storageUrls = this.dedupeStrings([...flat, ...recursive])
      // filter out mac junk
      .filter((u) => !u.includes('/.DS_Store'))
      .sort((a, b) => a.localeCompare(b));

    // 2) Merge RTDB gallery if any
    const rawGallery = (this.boat?.gallery || []).filter(Boolean);
    let galleryUrls: string[] = [];

    if (rawGallery.length) {
      const resolved = await Promise.all(rawGallery.map((p) => this.resolvePathToDownloadUrl(p)));
      galleryUrls = resolved.filter((u): u is string => !!u);
    }

    // 3) Optional fallback to boat.image/heroImage if listing is empty
    const fallbackCandidates = [this.boat?.heroImage, this.boat?.image].filter(Boolean) as string[];
    let fallbackUrls: string[] = [];
    if (!storageUrls.length && fallbackCandidates.length) {
      const resolved = await Promise.all(fallbackCandidates.map((p) => this.resolvePathToDownloadUrl(p)));
      fallbackUrls = resolved.filter((u): u is string => !!u);
    }

    this.boatImageUrls = this.dedupeStrings([...storageUrls, ...galleryUrls, ...fallbackUrls]);
  }

  /**
   * ✅ RTDB alignment:
   * backendskippers/<mainpageId>/skippers/<skipperId>
   */
  private async loadSkipperFromRtdb(mainpageId: string): Promise<void> {
    const collectionName = (OBJECTNAME as any).bnSkippers || 'backendskippers';

    const node = await this.storeDb.getObject<any>(collectionName, `${mainpageId}/skippers`);

    if (!node || typeof node !== 'object') {
      this.skipper = undefined;
      return;
    }

    const skipperList = Object.keys(node)
      .map((k) => ({ key: k, ...(node[k] || {}) }))
      .filter((x) => x && typeof x === 'object');

    if (!skipperList.length) {
      this.skipper = undefined;
      return;
    }

    const candidates = skipperList.filter((s: any) => s.showOnSite !== false);

    const chosen = (candidates.length ? candidates : skipperList).sort(
      (a: any, b: any) => Number(a.sortOrder ?? 9999) - Number(b.sortOrder ?? 9999)
    )[0];

    const rawPhotos: string[] =
      (Array.isArray(chosen.photos_json) && chosen.photos_json.length
        ? chosen.photos_json
        : Array.isArray(chosen.photos) && chosen.photos.length
          ? chosen.photos
          : chosen.photo
            ? [chosen.photo]
            : []) || [];

    let photoUrls: string[] = [];
    if (rawPhotos.length) {
      const resolved = await Promise.all(rawPhotos.map((p: string) => this.resolvePathToDownloadUrl(p)));
      photoUrls = resolved.filter((u): u is string => !!u);
    }

    // Storage fallback: mainpages/<id>/skippers/*
    if (!photoUrls.length) {
      const skipperRoot = `${this.storageRootFolder}/${this.mainpageId}/skippers`;
      const flat = await this.storeDb.listImageUrlsFlat(skipperRoot);
      const recursive = await this.storeDb.listImageUrlsRecursive(skipperRoot);
      photoUrls = this.dedupeStrings([...flat, ...recursive])
        .filter((u) => !u.includes('/.DS_Store'))
        .sort((a, b) => a.localeCompare(b));
    }

    const spoken = Array.isArray(chosen.spokenLanguages) ? chosen.spokenLanguages : [];
    const langsFromSpoken = spoken.map((x: any) => x?.label).filter(Boolean);
    const langsFromPlain = Array.isArray(chosen.languages) ? chosen.languages : [];

    this.skipper = {
      ownerId: chosen.ownerId || this.mainpage?.ownerId || mainpageId,
      skipperId: chosen.skipperId || chosen.key,
      name: chosen.name || chosen.fullName || chosen.displayName || 'Your skipper',
      role: chosen.role || 'Skipper',
      shortBio: chosen.shortBio || chosen.bio || '',
      experienceYears: chosen.yearsExperience || chosen.experienceYears || chosen.yearsAtSea,
      languages: langsFromSpoken.length ? langsFromSpoken : langsFromPlain,
      photoUrls,
    };
  }

  /** Events stored under /backendevents/<mainpageId>/events */
  private async loadEvents(mainpageId: string): Promise<void> {
    // New RTDB structure: backendowners/events/{boatId}/{eventId}
    const boatId = this.boat?.boatId || '1000001';
    const node = await this.storeDb.getObject<any>('backendowners/events', `${boatId}`);

    if (!node) {
      this.events = [];
      return;
    }

    const rawArray = this.objectToArray(node);
    const mapped = await Promise.all(rawArray.map((row) => this.mapToEventCardAsync(row)));
    this.events = mapped.filter((ev) => !!ev?.eventId);
  }

  private async mapToEventCardAsync(row: any): Promise<EventCard> {
    const eventId = row.eventId || row.id || row.key || '';
    const title = row.title || 'Boat event';
    const subtitle = row.subtitle || row.tagline || '';

    let imageUrls: string[] = [];

    // 1) RTDB-defined gallery
    const rawImages: string[] =
      (Array.isArray(row.gallery) && row.gallery.length
        ? row.gallery
        : Array.isArray(row.images_json) && row.images_json.length
          ? row.images_json
          : []) || [];

    if (rawImages.length) {
      const resolved = await Promise.all(rawImages.map((p: string) => this.resolvePathToDownloadUrl(p)));
      imageUrls = resolved.filter((u): u is string => !!u);
    }

    // 2) STORAGE FALLBACK: mainpages/<id>/events/<eventId>/*
    if (!imageUrls.length && eventId) {
      const eventRoot = `${this.storageRootFolder}/${this.mainpageId}/events/${eventId}`;
      const flat = await this.storeDb.listImageUrlsFlat(eventRoot);
      const recursive = await this.storeDb.listImageUrlsRecursive(eventRoot);
      imageUrls = this.dedupeStrings([...flat, ...recursive]).filter((u) => !u.includes('/.DS_Store'));
    }

    const durationLabel =
      row.durationLabel || row.duration || (row.durationHours ? `${row.durationHours}h` : '');

    const locationLabel = row.locationLabel || row.location || row.area || '';
    const footerLeft = row.footerLeft || row.footer || (row.withSkipper ? 'With skipper' : '');
    const ctaLabel = row.ctaLabel || 'View event';

    return {
      eventId,
      title,
      subtitle,
      imageUrls,
      durationLabel,
      locationLabel,
      footerLeft,
      ctaLabel,
    };
  }

  // ---------------------------------------------------------------------------
  // STORAGE RESOLUTION
  // ---------------------------------------------------------------------------

  private async resolvePathToDownloadUrl(path?: string | null): Promise<string | undefined> {
    if (!path) return undefined;
    const p = String(path).trim();
    if (!p) return undefined;

    // already full URL (tokened)
    if (/^https?:\/\//i.test(p)) return p;

    const clean = p.replace(/^\/+/, '');

    // Already mainpages/...
    if (clean.startsWith(`${this.storageRootFolder}/`)) {
      return this.tryGetDownloadUrl(clean);
    }

    // Starts with owner-home-xxx/...
    if (/^owner-home-[^/]+\//i.test(clean)) {
      return this.tryGetDownloadUrl(`${this.storageRootFolder}/${clean}`);
    }

    // Otherwise relative to this mainpage folder (bucket aligned)
    return this.tryGetDownloadUrl(`${this.storageRootFolder}/${this.mainpageId}/${clean}`);
  }

  private async tryGetDownloadUrl(fullStoragePath: string): Promise<string | undefined> {
    try {
      return await this.storeDb.getDownloadUrl(fullStoragePath);
    } catch {
      return undefined;
    }
  }

  // ---------------------------------------------------------------------------
  // TEMPLATE GETTERS (BOAT-FIRST)
  // ---------------------------------------------------------------------------

  get aboutBoatImageUrls(): string[] {
    return this.boatImageUrls.length ? this.boatImageUrls : [];
  }

  get aboutTitle(): string {
    return this.boat?.name || this.boat?.model || this.mainpage?.aboutBoatTitle || 'About the boat';
  }

  get aboutText(): string {
    return this.boat?.detailedDescription || this.boat?.shortDescription || this.mainpage?.aboutBoatText || '';
  }

  get aboutBadges(): string[] {
    const comfort = (this.boat?.comfort || []).filter(Boolean).slice(0, 6);
    const mp = (this.mainpage?.aboutBoatBadges_json || []).filter(Boolean);
    return this.dedupeStrings([...comfort, ...mp]);
  }

  get aboutLink(): any {
    return this.boat?.ctaLink || this.mainpage?.aboutBoatLink || '/boats';
  }

  get aboutLinkLabel(): string {
    return this.boat?.ctaLabel || 'See full specs';
  }

  get skipperPrimaryPhoto(): string | undefined {
    return this.skipper?.photoUrls?.length ? this.skipper.photoUrls[0] : undefined;
  }

  get skipperLink(): any[] {
    return ['/owners', this.mainpageId, 'skipper'];
  }

  // ---------------------------------------------------------------------------
  // UI HELPERS
  // ---------------------------------------------------------------------------

  heroBadgeClass(badge: HeroBadge): string {
    return badge.style === 'dark'
      ? 'badge text-bg-dark badge-rounded'
      : 'badge text-bg-light border badge-rounded';
  }

  heroBadgeIconClasses(badge: HeroBadge): any {
    return badge.icon ? ['bi', badge.icon, 'me-1'] : null;
  }

  experienceIconClasses(item: ExperienceItem): any {
    return item.icon ? ['bi', item.icon, 'fs-4', 'd-block', 'mb-2'] : ['bi', 'fs-4', 'd-block', 'mb-2'];
  }

  // ---------------------------------------------------------------------------
  // SMALL UTILS
  // ---------------------------------------------------------------------------

  private dedupeStrings(items: string[]): string[] {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const it of items) {
      if (!it) continue;
      if (seen.has(it)) continue;
      seen.add(it);
      out.push(it);
    }
    return out;
  }

  private objectToArray(obj: any): any[] {
    if (!obj || typeof obj !== 'object') return [];
    return Object.keys(obj).map((key) => ({ key, ...(obj[key] || {}) }));
  }
}
