import { Component, ChangeDetectionStrategy, OnDestroy, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { Subscription } from 'rxjs';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

interface MainpageDoc {
  mainpageId: string;
  siteName?: string;
  heroTitle?: string;
  aboutBoatTitle?: string;  // sometimes the boat name
  ownerId?: string;
}

@Component({
  selector: 'app-about-boat-space',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './about-boat-space.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AboutBoatSpaceComponent implements OnInit, OnDestroy {
  loading = false;
  error?: string;

  mainpageId?: string;
  mainpage?: MainpageDoc;

  private sub = new Subscription();

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private storeDb: StoreDbService
  ) {}

  ngOnInit(): void {
    this.sub.add(
      this.route.queryParamMap.subscribe(pm => {
        const id = (pm.get('mainpage') || '').trim();
        this.mainpageId = id || undefined;
        void this.loadMainpage();
      })
    );
  }

  ngOnDestroy(): void {
    this.sub.unsubscribe();
  }

  private async loadMainpage(): Promise<void> {
    this.error = undefined;
    this.mainpage = undefined;

    if (!this.mainpageId) {
      // This page is meant to be used in a boat space context
      this.error = 'Missing boat space context (mainpage).';
      return;
    }

    this.loading = true;
    try {
      const mainpagePath = (OBJECTNAME as any).bnMainpage || 'backendmainpage';
      const doc = await this.storeDb.getObject<any>(mainpagePath, this.mainpageId);

      if (!doc || typeof doc !== 'object') {
        this.error = `Boat space "${this.mainpageId}" not found.`;
        return;
      }

      this.mainpage = {
        mainpageId: doc.mainpageId || this.mainpageId,
        siteName: doc.siteName,
        heroTitle: doc.heroTitle,
        aboutBoatTitle: doc.aboutBoatTitle,
        ownerId: doc.ownerId
      };
    } catch (e: any) {
      console.error(e);
      this.error = e?.message || 'Failed to load boat space info.';
    } finally {
      this.loading = false;
    }
  }

  // Simple helpers for CTA buttons (keep query param)
  goToMainpageHome(): void {
    if (!this.mainpageId) return;
    this.router.navigate(['/mainpage'], { queryParams: { mainpage: this.mainpageId } });
  }

  goToBookings(): void {
    if (!this.mainpageId) return;
    this.router.navigate(['/mainpage/book'], { queryParams: { mainpage: this.mainpageId } });
  }

  goToContact(): void {
    // global contact page; you can also add queryParams to indicate context
    this.router.navigate(['/contactus'], {
      queryParams: this.mainpageId ? { mainpage: this.mainpageId } : {}
    });
  }

  get displayTitle(): string {
    const mp = this.mainpage;
    return (
      mp?.aboutBoatTitle ||
      mp?.siteName ||
      mp?.heroTitle ||
      this.mainpageId ||
      'Boat space'
    );
  }
}
