import {
  Component,
  OnDestroy,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef
} from '@angular/core';
import { Subscription } from 'rxjs';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

type BookingStatus =
  | 'requested'
  | 'confirmed'
  | 'cancelled'
  | 'declined'
  | 'expired'
  | 'completed';

interface BookingDoc {
  bookingId: string;

  status: BookingStatus;
  type: 'boat' | 'event';

  mainpageId: string; // owner-home-xxx
  ownerId: string;    // owner-home-xxx
  boatId: string;     // "1000002"
  boatSlug?: string;
  eventId?: string;

  customer?: {
    uid?: string;
    email?: string;
    fullName?: string;
    phone?: string;
  };

  party?: {
    adults?: number;
    children?: number;
    total?: number;
  };

  time?: {
    startAt?: string | number; // ISO string in your dump
    endAt?: string | number;
  };

  locations?: {
    pickup?: { label?: string; lat?: number; lng?: number };
    dropoff?: { label?: string; lat?: number; lng?: number };
  };

  notes?: {
    customerNote?: string;
    ownerNote?: string;
  };

  audit?: {
    createdAt?: string | number;
    updatedAt?: string | number;
    requestedAt?: string | number;
    confirmedAt?: string | number;
    cancelledAt?: string | number;
    cancelledBy?: 'owner' | 'customer' | string;
  };

  pricing?: {
    currency?: string;
    baseAmount?: number;
    extrasAmount?: number;
    serviceFee?: number;
    taxAmount?: number;
    depositAmount?: number;
    totalAmount?: number;
  };

  extras?: any;
}

interface OwnerProfile {
  ownerId: string;         // RTDB key like owner-home-layali
  primaryUserId: string;   // Firebase auth uid
  siteName?: string;
  mainpageId?: string;
}

@Component({
  selector: 'app-owner-bookings',
  templateUrl: './owner-bookings.component.html',
  styleUrls: ['./owner-bookings.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OwnerBookingsComponent implements OnInit, OnDestroy {
  loading = false;
  error?: string;

  // shown in template header
  mainpageId?: string;

  owner?: OwnerProfile;

  // FULL list for owner
  bookings: BookingDoc[] = [];

  // TEMPLATE BINDS to these => MUST be public
  status: 'all' | BookingStatus = 'all';
  q = '';
  filtered: BookingDoc[] = [];

  private subs = new Subscription();

  constructor(
    private storeDb: StoreDbService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.subs.add(
      this.storeDb.authState$.subscribe(user => {
        if (!user) {
          this.owner = undefined;
          this.bookings = [];
          this.filtered = [];
          this.mainpageId = undefined;
          this.error = 'Not logged in.';
          this.cdr.markForCheck();
          return;
        }
        void this.loadOwnerAndBookings(user.uid);
      })
    );
  }

  ngOnDestroy(): void {
    this.subs.unsubscribe();
  }

  // Called by your Refresh button
  reload(): void {
    const user = (this.storeDb as any).currentUser?.();
    const uid = user?.uid;
    if (!uid) {
      this.error = 'Not logged in.';
      this.cdr.markForCheck();
      return;
    }
    void this.loadOwnerAndBookings(uid);
  }

  // ---------------------------------------------------------------------------
  // Main flow
  // ---------------------------------------------------------------------------

  private async loadOwnerAndBookings(uid: string): Promise<void> {
    this.loading = true;
    this.error = undefined;
    this.bookings = [];
    this.filtered = [];
    this.owner = undefined;
    this.mainpageId = undefined;
    this.cdr.markForCheck();

    try {
      const owner = await this.resolveOwnerByPrimaryUserId(uid);
      if (!owner) {
        this.error = 'No owner profile found for this account. Please create your owner profile first.';
        return;
      }

      this.owner = owner;
      this.mainpageId = owner.mainpageId || owner.ownerId;

      const all = await this.loadBookingsFlat();
      const mine = all
        .filter(b => (b.ownerId || '') === owner.ownerId)
        .map(b => this.normalizeBooking(b));

      // sort newest first (createdAt > requestedAt > startAt)
      mine.sort((a, b) => this.sortKey(b) - this.sortKey(a));

      this.bookings = mine;

      // apply UI filters initially
      this.applyFilters();
    } catch (e: any) {
      console.error('[owner-bookings] load error', e);
      this.error = e?.message || 'Failed to load bookings.';
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  // ---------------------------------------------------------------------------
  // Owner resolution (your structure: backendowners/<ownerId>.primaryUserId = uid)
  // ---------------------------------------------------------------------------

  private async resolveOwnerByPrimaryUserId(uid: string): Promise<OwnerProfile | null> {
    const ownersPath = (OBJECTNAME as any).bnOwners || 'backendowners';

    // 1) Try indexed style if you ever add it: backendowners/primaryUserId/<uid>
    try {
      const indexed = await this.storeDb.getObject<any>(ownersPath, `primaryUserId/${uid}`);
      if (typeof indexed === 'string' && indexed.trim()) {
        const ownerId = indexed.trim();
        const ownerObj = await this.storeDb.getObject<any>(ownersPath, ownerId);
        if (ownerObj && typeof ownerObj === 'object') {
          return {
            ownerId,
            primaryUserId: ownerObj.primaryUserId || uid,
            siteName: ownerObj.siteName,
            mainpageId: ownerObj.mainpageId || ownerId
          };
        }
        return { ownerId, primaryUserId: uid, mainpageId: ownerId };
      }
      if (indexed && typeof indexed === 'object') {
        const ownerId = indexed.ownerId || indexed.id || indexed.key;
        if (ownerId) {
          return {
            ownerId,
            primaryUserId: indexed.primaryUserId || uid,
            siteName: indexed.siteName,
            mainpageId: indexed.mainpageId || ownerId
          };
        }
      }
    } catch {
      // ignore, fallback scan
    }

    // 2) Scan backendowners root and match primaryUserId
    const ownersNode = await this.storeDb.getObject<any>(ownersPath, -1);
    if (!ownersNode || typeof ownersNode !== 'object') return null;

    for (const ownerId of Object.keys(ownersNode)) {
      const o = ownersNode[ownerId];
      if (o && typeof o === 'object' && o.primaryUserId === uid) {
        return {
          ownerId,
          primaryUserId: uid,
          siteName: o.siteName,
          mainpageId: o.mainpageId || ownerId
        };
      }
    }

    return null;
  }

  // ---------------------------------------------------------------------------
  // Bookings
  // ---------------------------------------------------------------------------

  private async loadBookingsFlat(): Promise<BookingDoc[]> {
    const bookingsPath = (OBJECTNAME as any).bnBookings || 'backendbookings';
    const node = await this.storeDb.getObject<any>(bookingsPath, -1);

    if (!node || typeof node !== 'object') return [];

    const out: BookingDoc[] = [];
    for (const bookingId of Object.keys(node)) {
      const b = node[bookingId];
      if (!b || typeof b !== 'object') continue;

      // IMPORTANT: your dump already stores customer, party, time as expected :contentReference[oaicite:1]{index=1}
      out.push({
        bookingId: b.bookingId || bookingId,
        status: b.status || 'requested',
        type: b.type || 'boat',
        mainpageId: b.mainpageId,
        ownerId: b.ownerId,
        boatId: b.boatId,
        boatSlug: b.boatSlug,
        eventId: b.eventId,
        customer: b.customer,
        party: b.party,
        time: b.time,
        locations: b.locations,
        notes: b.notes,
        audit: b.audit,
        pricing: b.pricing,
        extras: b.extras
      });
    }

    return out;
  }

  private normalizeBooking(b: BookingDoc): BookingDoc {
    // ensure numbers + totals
    const adults = Number(b.party?.adults || 0);
    const children = Number(b.party?.children || 0);
    const total = b.party?.total != null ? Number(b.party.total) : (adults + children);

    return {
      ...b,
      bookingId: b.bookingId,
      status: (b.status || 'requested') as BookingStatus,
      type: (b.type || 'boat') as 'boat' | 'event',
      party: {
        adults: adults || 0,
        children: children || 0,
        total: total || 0
      },
      customer: {
        uid: b.customer?.uid,
        email: b.customer?.email,
        fullName: b.customer?.fullName,
        phone: b.customer?.phone
      },
      time: {
        startAt: b.time?.startAt,
        endAt: b.time?.endAt
      }
    };
  }

  private sortKey(b: BookingDoc): number {
    return (
      this.toMillis(b.audit?.createdAt) ||
      this.toMillis(b.audit?.requestedAt) ||
      this.toMillis(b.time?.startAt) ||
      0
    );
  }

  private toMillis(v: any): number {
    if (!v) return 0;
    if (typeof v === 'number') return v;

    const s = String(v).trim();
    if (!s) return 0;

    // if numeric string
    const n = Number(s);
    if (!Number.isNaN(n) && n > 0) return n;

    const d = Date.parse(s);
    return Number.isNaN(d) ? 0 : d;
  }

  // ---------------------------------------------------------------------------
  // Template methods (MUST be public)
  // ---------------------------------------------------------------------------

  count(s: 'all' | BookingStatus): number {
    const list = this.bookings || [];
    if (s === 'all') return list.length;
    return list.filter(b => b.status === s).length;
  }

  setFilter(s: 'all' | BookingStatus): void {
    this.status = s;
    this.applyFilters();
  }

  applyFilters(): void {
    const query = (this.q || '').trim().toLowerCase();

    let list = [...(this.bookings || [])];

    // status filter
    if (this.status !== 'all') {
      list = list.filter(b => (b.status || '') === this.status);
    }

    // text search
    if (query) {
      list = list.filter(b => {
        const hay = [
          b.bookingId,
          b.boatId,
          b.boatSlug,
          b.eventId,
          b.customer?.fullName,
          b.customer?.email,
          b.customer?.uid,
          b.mainpageId,
          b.ownerId
        ]
          .filter(Boolean)
          .join(' ')
          .toLowerCase();

        return hay.includes(query);
      });
    }

    // keep sorted newest first
    list.sort((a, b) => this.sortKey(b) - this.sortKey(a));

    this.filtered = list;
    this.cdr.markForCheck();
  }

  formatDate(v: any): string {
    if (!v) return '—';

    // supports epoch millis or ISO string
    const d =
      typeof v === 'number'
        ? new Date(v)
        : typeof v === 'string'
          ? new Date(v)
          : null;

    if (!d || isNaN(d.getTime())) return String(v);

    return d.toLocaleString(undefined, {
      year: 'numeric',
      month: 'short',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // ---------------------------------------------------------------------------
  // Actions (best-effort write; if your StoreDbService doesn't support it, it will error cleanly)
  // ---------------------------------------------------------------------------

  async confirm(b: BookingDoc): Promise<void> {
    await this.updateStatus(b, 'confirmed');
  }

  async decline(b: BookingDoc): Promise<void> {
    await this.updateStatus(b, 'declined');
  }

  async cancel(b: BookingDoc): Promise<void> {
    await this.updateStatus(b, 'cancelled', { cancelledBy: 'owner', cancelledAt: new Date().toISOString() });
  }

  async markCompleted(b: BookingDoc): Promise<void> {
    await this.updateStatus(b, 'completed');
  }

  private async updateStatus(
    b: BookingDoc,
    next: BookingStatus,
    auditPatch?: Partial<NonNullable<BookingDoc['audit']>>
  ): Promise<void> {
    try {
      const bookingsPath = (OBJECTNAME as any).bnBookings || 'backendbookings';
      const bookingId = b.bookingId;

      const nowIso = new Date().toISOString();
      const patch: Partial<BookingDoc> = {
        status: next,
        audit: {
          ...(b.audit || {}),
          updatedAt: nowIso,
          ...(next === 'confirmed' ? { confirmedAt: nowIso } : {}),
          ...(auditPatch || {})
        }
      };

      // Optimistic UI
      b.status = next;
      b.audit = patch.audit as any;
      this.applyFilters();

      // Best-effort RTDB write with whatever method exists on your StoreDbService
      const svc: any = this.storeDb as any;

      if (typeof svc.patchObject === 'function') {
        await svc.patchObject(bookingsPath, bookingId, patch);
      } else if (typeof svc.updateObject === 'function') {
        await svc.updateObject(bookingsPath, bookingId, patch);
      } else if (typeof svc.setObject === 'function') {
        const full = { ...(b as any), ...(patch as any) };
        await svc.setObject(bookingsPath, bookingId, full);
      } else {
        throw new Error('No RTDB write method available in StoreDbService (patch/update/set).');
      }
    } catch (e: any) {
      console.error('[owner-bookings] updateStatus error', e);
      this.error = e?.message || 'Failed to update booking status.';
      // reload to be safe
      this.cdr.markForCheck();
    }
  }
}
